import { Component, computed, ElementRef, HostBinding, inject, input, Renderer2 } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
  host: {
    '[tabindex]': 'order()',
  },
})
export class PctAvatar {
  protected order: () => number;
  constructor() {
    this.order = () => 2;
  }
}
